import click

class MyCommand(click.Command):
    pass

class MyGroup(click.Group):
    command_class = MyCommand
    group_class = type

@click.group(cls=MyGroup)
def cli():
    pass

# concise form
@cli.command
def a():
    pass

# called form
@cli.command()
def b():
    pass

# explicit override
@cli.command(cls=click.Command)
def c():
    pass

# nested group concise
@cli.group
def sub():
    pass

@sub.command
def d():
    pass

print(type(a).__name__, type(b).__name__, type(c).__name__, type(sub).__name__, type(d).__name__)
EOF
